import { LiveStatus, Button, Card } from "march/ui"

// kurabiye kavanozu: her alışta durum satırı kalanı söyler; biterse araya girerek (assertive) uyarır
export function CookieJar() {
  let $left = 5
  return <Card title="Kurabiye kavanozu 🍪">
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Button size="sm" disabled={() => $left === 0} on:click={() => $left--}>Bir tane al</Button>
      <Button size="sm" variant="ghost" on:click={() => $left = 5}>Doldur</Button>
    </div>
    {() => <LiveStatus politeness={$left === 0 ? "assertive" : "polite"} text={() => ($left ? `${"🍪".repeat($left)} ${$left} kurabiye kaldı` : "Kavanoz boş!")} />}
  </Card>
}

import { LiveStatus, Checkbox, Card } from "march/ui"

// e-posta listesi: kutular işaretlendikçe altta "N ileti seçildi" okunur; yardım satırı listeye aria-describedby ile bağlı
const MAILS = ["Fatura hazır", "Toplantı daveti", "Haftalık bülten", "Şifre değişti"]

export function MailSelection() {
  let $picked: string[] = []
  const flip = (m: string, on: boolean) => { $picked = on ? [...$picked, m] : $picked.filter((x) => x !== m) }
  return <Card title="Gelen kutusu">
    <div aria-describedby="mail-help" sx={{ flex: "col", gap: 1 }}>
      {MAILS.map((m) => <Checkbox label={m} onChange={(on: boolean) => flip(m, on)} />)}
    </div>
    <LiveStatus as="p" help="Toplu işlem için iletileri işaretleyin." helpId="mail-help"
      text={() => ($picked.length ? `${$picked.length} ileti seçildi` : "Seçili ileti yok")} />
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { LiveStatusLab } from "./LiveStatusLab.tsx"

// LiveStatusLab'in testleri: kaydedince Testler sekmesinde çalışır
test("durum satırı role=status, kibar; class ve öznitelikler köke gider", () => {
  const s = renderTest(() => <LiveStatusLab />)
  const st = s.get(".lab-count")
  expect(st?.getAttribute("role")).toBe("status")
  expect(st?.getAttribute("aria-live")).toBe("polite")
  expect(st?.getAttribute("data-kind")).toBe("sayaç")
})

test("text erişimcisi düğmeyle güncellenir", async () => {
  const s = renderTest(() => <LiveStatusLab />)
  await s.click("Bir tane ekle")
  await s.click("Bir tane ekle")
  expect(s.get(".lab-count")?.textContent).toBe("2 öğe eklendi")
})

test("visible={false} görsel olarak gizler, as öğeyi seçer", () => {
  const s = renderTest(() => <LiveStatusLab />)
  const hidden = s.get(".lab-hidden")
  expect(hidden?.tagName).toBe("P")
  expect(hidden?.classList.contains("m-sr-only")).toBe(true)
  expect(s.find("Children ile söylenen, araya giren durum")?.getAttribute("aria-live")).toBe("assertive")
})

test("help satırı helpId ve helpClass ile durumdan önce gelir", () => {
  const s = renderTest(() => <LiveStatusLab />)
  const help = s.get("#lab-help")
  expect(help?.classList.contains("lab-help")).toBe(true)
  expect(help?.nextElementSibling?.textContent).toBe("Yardım satırı önce gelir")
})
